// Entry
// ---------------------------------------------------------------------------

const USAGE = `usage: bun .claude/skills/plan-steps/tk.ts <command> …

  me                                                 (PAT, project, seam, current sprint, agent session id and its source)
  plan next [--json] [--request <key|id>]            (pull the next planning request — a ready agent ticket labelled \`planning\` — and print
                                                      its key, title, full description and its comments (a promoted report carries the
                                                      human's "Promoted to plan" note there); exit 5 when the planning queue is empty;
                                                      the subject for a /plan-steps run the user gave no details for.
                                                      Under the header line it prints the request's plan mode —
                                                      \`Plan mode: <label> → /<skill> (<TIER>[, run review|quick])\`, or
                                                      \`Plan mode: none — route with the plan-steps router\`; with --json
                                                      \`planMode: { label, skill, tier, run } | null\` — from the plan-mode label
                                                      chosen in the New plan modal: plan-full → /plan-steps (FULL), plan-quick →
                                                      /plan-quick (MEDIUM), plan-single → /plan-steps (SMALL, one ticket),
                                                      plan-run → /plan-run (SMALL, run at once, review item after), plan-run-quick →
                                                      /plan-run-quick (SMALL, run at once, no review item); several mode labels →
                                                      the first in that order wins, with a warning; plan-split → /plan-steps (SPLIT)
                                                      comes first. A request generated by a split also prints
                                                      \`Split from: <KEY> <title>\` under the mode line —
                                                      \`splitFrom: { key, id, title } | null\` with --json.
                                                      Under \`Plan mode:\` it prints the \`Title:\` line — \`Title: none — "<provisional
                                                      title>" is provisional; name it: tk.ts plan title <KEY> "<title>"\` for a request
                                                      filed without a title (the planner names it), or \`Title: set by its author —
                                                      keep it\`; \`titlePending: boolean\` with --json.
                                                      Directly under \`Title:\` it prints the \`Effort:\` line — \`Effort: <Label> — set
                                                      by a person; the master carries it\`, \`Effort: <Label> — estimated by the auto
                                                      worker; a default for the master\`, or \`Effort: none\`; \`effort\` (the value or
                                                      null) and \`effortEstimated\` with --json.
                                                      --request <key|id> — or, without the flag, the environment variable
                                                      TICKETING_PLAN_REQUEST (a ticket id; the auto worker sets it) — pins the pull:
                                                      exactly that request or nothing (exit 5, \`the pinned plan request <key|id> is not
                                                      ready any more — nothing pulled\`, never another request); a server that cannot
                                                      pin is asked once more without it, with a warning)
  plan title <request key|id> <title | ->            (name a plan request that was filed without a title — POST
                                                      /api/tickets/:id/plan-request-title; stdin when \`-\`; a leading \`# \` and a tier
                                                      suffix — (quick), (single), (run), (run-quick) — are stripped; at most 256
                                                      characters (every ticket title is — the server answers 400 beyond it, and tk.ts
                                                      cuts a longer title it composes, with a warning); prints \`request <KEY> titled
                                                      "<title>"\`; a request that already has a title is left as it is, exit 0.
                                                      \`plan open --request\` does this by itself — the command is for a split)
  plan split request [--from <origin key|id>] -      (stdin = \`# <title>\` + \`**Plan mode:** plan-full|plan-quick|plan-single|plan-run|plan-run-quick\`
                                                      + the prompt: ONE generated plan request, filed agent-handled with the \`planning\` and
                                                      mode labels under the origin (the request \`plan next\` pulled; none = a prompt-driven
                                                      split), then parked for a person with POST /api/tickets/:id/plan-request-submit;
                                                      prints \`request <KEY> (<id>) in_review handler human labels planning, <mode> — from
                                                      <ORIGIN|prompt>; awaiting Approve for Planning\`; \`plan-split\` is refused, exit 2)
  plan split submit <key>                            (re-park a draft a failed \`plan split request\` left in \`backlog\`)
  plan split status [<origin>] [--json]              (with an origin: every plan request it generated with its state — draft, awaiting, queued,
                                                      planning, planned, done, cancelled — and the plan filed under it; without: this token's
                                                      unfinished pulls, the \`in_progress\` plan requests with no plan under them; exit 5 when none)
  plan split release <origin> --tokens-in N --tokens-out M --note estimated
                                                     (the end of a split: records the planning usage on the origin once, comments
                                                      \`Plan split — <n> plan requests filed\` with the table, moves the origin to \`in_review\`
                                                      and tries the handler flip; refused while it generated nothing or a request is still
                                                      a draft — \`plan split --help\` for details)
  plan open [--scope S|M|L] [--request <key|id>] -   (stdin = \`# <title>\` + \`## Original prompt\` — a leading "Plan —" is stripped; creates the
                                                      story, a provisional master filed with the \`plan\` label and the claimed planning ticket
                                                      — run it BEFORE any research; --request is the planning request from \`plan next\`:
                                                      the master is filed under it and carries a
                                                      \`**Planning request:** TICK-nn\` header — keep that line in the \`plan master\` document;
                                                      a request filed without a title is given the plan's title, tier suffix stripped —
                                                      \`request <KEY> titled "<title>"\`, a failure is only a warning;
                                                      warns when the document has no \`## Original prompt\` (the original-prompt section))
  plan calibrate [--json] [--examples N] [--bucket sprint|week|month]
                                                     (sizing brief from the estimate-accuracy report — tokens-per-point rate, verdicts
                                                      overall and by size, sprint history, trend, example tickets and guidance;
                                                      run it right after \`plan open\` and size the steps accordingly)
  plan note <master> <text | ->                      (comment on the planning ticket + heartbeat)
  plan master <master> -                             (stdin = the final master document; also rewrites the master of a plan a human sent back
                                                      for revision — \`in_review\` + handler \`agent\`, via POST /api/tickets/:id/plan-revision;
                                                      warns when the document has no \`## Original prompt\` section; the document's
                                                      \`**Effort:** very high|high|medium|small\` header — preamble only, optional; Very High only where a person already set it, else sent as High — is
                                                      sent as the master's \`effort\` and its absence clears it; prints
                                                      \`· effort <Label>\` / \`· effort none\`. Only the master carries an effort: the
                                                      header on any other document is ignored with a warning)
  plan step <master> -                               (stdin = step document)
  plan question <master> -                           (stdin = question document)
  plan external <master> -                           (stdin = external document — \`# External NN — title\` + \`**Project:** KEY\` +
                                                      \`**Category:** <one of the 14 category labels>\` + \`**Blocks:** step-NN, … | all | none\`:
                                                      a request to another project, filed with the \`external\` and category labels and
                                                      parked for a person at once — human-only; \`plan release\` wires its edges like a
                                                      question's, but it holds only the steps it blocks, never the story)
  plan update <master> <ref> -                       (\`step-NN\` / \`fix-NN\` while they are backlog drafts; \`master\` also during a revision)
  plan release <master> [--hold | --run] [--tokens-in N --tokens-out M] [--note <text>]
                                                     (barriers for multi-wave plans + edges + a points estimate on every ticket — the server derives the
                                                      token estimates; records the planning usage and closes the planning ticket;
                                                      comments the planning request and puts it in review for its human;
                                                      then ALWAYS parks the plan for human approval: every step, barrier and the
                                                      master stay in \`backlog\` and the master goes \`in_review\` + handler human.
                                                      "Confirm Plan" on the master is what promotes them to todo; "Revise Plan"
                                                      sends it back to /plan-steps (tk.ts plan revise).
                                                      --hold = do not even park it — everything stays backlog, master untouched;
                                                      --run = a single-ticket plan carrying **Run:** review|quick starts at once: no parking,
                                                      master → todo, the story stays with this PAT (/plan-run, /plan-run-quick))
  plan revise [<master>] [--json]                    (the revision entry point: no argument lists the plans a human sent back —
                                                      master \`in_review\` + handler \`agent\` — newest first, exit 5 when there is none;
                                                      with a master it takes the plan's story, prints the ticket table and the
                                                      master's comments since the last release — the human's revision request.
                                                      The plan's tickets are still backlog drafts, so \`plan update <master> <ref> -\`
                                                      rewrites them in place; \`plan release\` then re-parks the master in review;
                                                      it also prints the \`### Revision N\` entry to append to the master's
                                                      \`## Prompt revisions\` section — \`promptRevisionsEntry\` with --json)
  plan latest [--all] [--json]                       (compatibility — newest non-cancelled master; /plan-go uses \`story find\`)
  plan list [--all] [--json]                         (open plans (newest first); --all adds done and cancelled: key, status, depends on, title)
  plan depends <master> <other-master|story> [--remove]
                                                     (this plan waits for another plan: the master and every wave-1 step block on the
                                                      other plan's master — \`--remove\` deletes those edges; \`done\` plans get no edge)
  plan status <master>                               (table + story/sprint footer + \`Depends on plans:\` + \`Planning request:\` +
                                                      \`Mode:\` + \`Effort: <Label>|none\` (the master ticket's effort) + points and
                                                      tokens per phase)
  plan tests <master> [--json] [<file>…]             (the story's test files: named by path in the master, step and fix documents, or
                                                      changed by a commit whose subject starts \`<ticket key>:\`; with files, one line
                                                      per file — \`story\` or \`foreign\`; always exit 0)
  plan landed <master> [--json] [--remote origin]    (per done ticket of the plan, whether its commits are on the sprint's integration
                                                      branch: one fetch, otherwise read-only; exit 0 all landed, 9 when one is not,
                                                      7 without a sprint repository — \`plan landed --help\`)
  plan cancel <master>                               (+ releases the story when this PAT holds it)
  story list [--json]                                (every story of the project, oldest first: sprint, owner, master, status, open/done)
  story find [<name>] [--json]                       (by name, story id or master key; no name = first untaken story with an open
                                                      plan — exit 5 when none; prints story · sprint · owner · master)
  story take <story-name|id|master-key>              (take the whole story before claiming its tickets; exit 3 when someone else holds it)
  story release <story-name|id|master-key>           (hand the story back — after \`done master\`)
  next [<story> | --story <id>] [--json]             (POST /api/work/next: the server assigns + starts ONE ready ticket of the story for this
                                                      PAT — the way agents acquire work; exit 5 nothing ready, 3 story taken by another agent)
  resume list [--json]                               (the stories THIS token left behind — owns, or holds an in_progress ticket in — with
                                                      mode \`planning\` (its planning ticket is still open: /plan-steps-resume) or \`execution\`
                                                      (/plan-resume), master, orphans and last heartbeat; exit 5 when there is nothing)
  resume <story> [--force] [--json]                  (POST /api/work/resume: take that story back for this token and print its mode, master,
                                                      planning ticket, in_progress orphans and — for a planning story — how far the planning
                                                      got; exit 3 taken by someone else, 10 this token's heartbeat is still fresh (another
                                                      session may be running it — --force overrides), 1 nothing of it is this token's)
  push <t> [--remote origin] [--max-rounds 20] [--dry-run]
                                                     (merge the sprint branch into HEAD and push until accepted; exit 6 merge conflict,
                                                      7 the sprint has no repository, 8 push failed; \`push --help\` for details)
  sync <t> [--from <rev>] [--remote origin] [--dry-run]
                                                     (from the PROJECT ROOT after \`done master\`: bring the sprint branch into the root's
                                                      local copy of it so the finished plan shows up in the main checkout; exit 9 when the
                                                      checkout was left as it was; \`sync --help\` for details)
  ready <master> [--json]                           (reporting: exit 5 when nothing is ready; prints \`waiting on plan TICK-nn …\` when another plan
                                                      gates it and \`waiting on external TICK-nn → KEY (promoted to … | not promoted yet)\` per open
                                                      external ticket — \`waitingOnExternal\` with --json, apart from \`waitingOnHuman\`)
  claim <master> <t>                                 (direct claim: only children of a ticket you hold or a story you own — otherwise \`next\`;
                                                      exit 3 already claimed or its story is taken by another agent, 4 blocked)
  start <master> <t>
  show <t> [--plan <master>] [--brief]               (+ Repository line and a ## Commits section; the open questions AND external tickets the
                                                      ticket waits on; \`External project:\` / \`Promoted to|from:\` lines; --brief, a plan
                                                      master only: without the sections only the orchestrator reads, the comments and the commits)
  comment <t> <body | -> [--commit <sha> | --no-commit] [--push]
                                                     (carries HEAD as the verified commit when the sprint has a repository; --push pushes first.
                                                      On a human ticket the comment is accepted but held for human approval — hidden from
                                                      every agent, this token included, until a human approves it or switches the ticket
                                                      to Agent — and is sent without a commit unless --commit or --push is given)
  heartbeat <t> [message]
  session <t> [--plan <master>] [--session <id>]     (re-report this agent session id on a ticket you hold — POST /api/tickets/:id/session;
                                                      exit 1 when you are not its assignee)
  done <t> [-m <comment>] [--tokens-in N --tokens-out M] [--note <text>] [--no-push] [--commit <sha> | --no-commit]
                                                     (runs \`push\` first when the sprint has a repository, then closes with that commit)
  fail <t> <reason | ->                              (release with the commit-free comment \`FAILED — reason\`)
  ask <master> <blocked-t | none> --title <title> [--class business-logic] (--body <text> | -)
                                                     (--class business-logic: a failing foreign test that protects a rule — writes
                                                      \`**Failure class:** business-logic\`; the body must carry \`## Failing tests\` and
                                                      \`## Options\`, else exit 2 and nothing is filed; no other class is a question)
  fix <master> <blocked-t> --title <title> [--class story|technical] [--answers <question>] (--body <text> | -)
                                                     (--class writes \`**Failure class:**\`; --answers <question ref|key> writes
                                                      \`**Answers:** question-NN\` — the answered question this fix turns into work,
                                                      class story unless given; \`ready\` lists answered ones without a fix as
                                                      \`answers to apply\` and \`plan status\` prints a \`Test failures:\` line)
  review file <master> -                             (stdin = \`# Review NN — title\` + body: one check a person must perform by hand.
                                                      Filed agent-handled with the \`question\` + \`review\` labels, then parked for its
                                                      human — handler human, \`in_review\` — which HOLDS the story's work queue)
  review list <master> [--failed] [--json]           (every review item with its verdict: draft, awaiting, reviewing, failed, passed,
                                                      cancelled; --failed = only the ones a human sent back; exit 5 when the list is empty)
  review submit <t> [--plan <master>] [-m <text>] [--tokens-in N --tokens-out M] [--note <text>] [--no-push]
                                                     (a FAILED item you fixed goes back for re-review: push, comment (while it is still
                                                      agent-handled), record the usage, then review-submit it — \`review --help\` for details)
  report file [--about <key>] -                      (stdin = \`# Report — title\` + body: a finding for a person to read. Filed agent-handled
                                                      with the \`report\` label, story-less and parentless, then parked for a person with
                                                      POST /api/tickets/:id/report-submit — handler human, \`in_review\`; holds NO queue)
  report list [--open] [--json]                      (the project's reports with their state: draft, awaiting, reading, resolved,
                                                      cancelled; --open = only the unsettled ones; exit 5 when the list is empty)
  summary show [<project key|id>] [--json]           (the project's public summary — abstract and ledger; default: the token's project)
  summary list [--json]                              (the summary cards of the organization's projects this token may read)
  summary propose <origin key|none> [--note <text>] [--dry-run] -
                                                     (stdin = a document with \`## Abstract\` and \`## Ledger\`: files a PROPOSAL — a human
                                                      question ticket a person approves or rejects; --dry-run prints the diff and files
                                                      nothing — \`summary --help\` for details)
  respond next [--json] [--request <commentId>]      (POST /api/work/respond-request: the oldest comment a human marked "Request agent
                                                      response", with its ticket and the comments up to it; GOAL-LOCKS this token until
                                                      it replies — exit 5 when nothing awaits, 2 when the PAT may not pull. --request,
                                                      else TICKETING_RESPOND_REQUEST, pins the pull to that one awaiting comment: exit 5
                                                      when it is not waiting any more, never another request. A respond request prints
                                                      \`Effort: <Label>\` or \`Effort: none — …\` under \`Kind:\`; an
                                                      ask ticket an \`Ask: yes — …\` line under those)
  respond post <key> --to <commentId> (- | --body <text> | --body-file <path>)
                                                     (the reply: POST /api/tickets/:id/comments { body, respondsTo } — lands in the
                                                      request's thread, marks it answered and clears the goal; never carries a commit)
  respond post <key> --summary <commentId> (- | --body <text> | --body-file <path>)
                                                     (the answer to a SIMPLIFY request — \`respond next\` printed \`Kind: simplify\`:
                                                      POST /api/comments/:commentId/summaries { body } — stored as a summary of that
                                                      comment, never a comment; clears the goal. Exactly one of --to and --summary)
  respond status [--json]                            (the goal this token holds — \`respond · KEY · comment <id>\` or
                                                      \`simplify comment <id> on KEY\` — or \`no goal\`)
  get <api path> [--json]                            (the read door: GET of one \`/api/…\` path with the token, printed as pretty JSON —
                                                      compact on one line with --json; any other path, a \`..\` segment or an absolute
                                                      URL is refused before anything is sent (exit 1, \`get only reads /api/… paths\`);
                                                      a non-2xx answer is exit 1 with the server's status and error code. Never writes)

Global option: --session <id>  the agent session id (else TICKETING_SESSION_ID, else CLAUDE_CODE_SESSION_ID, which Claude Code sets
  itself). REQUIRED by next, plan next, claim, plan open, start, done and session (exit 2 without one, before any request); sent on
  every transition when set. Never invent one, never put TICKETING_SESSION_ID in .env; \`me\` prints the resolved id and its source.
Global option: --flat  file the document as one plain description (\`sections: []\`) instead of splitting it at its \`## \` headings
  into typed sections (the default for every document: the preamble is the description, each \`## Heading\` a { type, content }
  section; readers reassemble them, so nothing changes for whoever reads the ticket through tk.ts).
Bodies: \`-\` reads stdin; --body <text> / --body-file <path> also work everywhere.
<master> = master ticket key or id; <t> = a ref in the plan (master, planning, step-NN, wave-N, question-NN, fix-NN, review-NN) or any key/id.
Review items: a human check filed AFTER the plan ran (/plan-review, /plan-review-fix). They are never estimated, never listed by
  \`ready\` and never served by \`next\`; while one is open its story's whole queue is held. See \`review --help\`.
Reports: an agent's finding for a person (/report, or any executor that notices something outside its ticket). Story-less, never
  estimated, never pauses a plan; a human replies, presses Promote to plan (it becomes a plan request \`plan next\` serves) or
  resolves it. See \`report --help\`.
Splits: a plan request whose deliverable is more plans (the \`plan-split\` label, or a text that asks for plans) gets NO story, master or
  planning ticket and no \`plan open\` — one \`plan split request --from <origin> -\` per plan cut, then \`plan split release <origin>\`.
  See \`plan split --help\`.
Phases (workflow on usage/estimates): plan-steps = planning ticket · plan-go = master + barriers · plan-go-step = steps, fixes, others.
Stories: \`plan open\` takes the plan's story while planning, \`plan release\` hands it back; /plan-go runs \`story find\` → \`story take\` → \`next\` (until exit 5) … → \`done master\` → \`story release\`.
Commits: agents commit only their ticket's files; \`push\` merges the sprint branch and pushes until accepted; \`comment\`/\`done\`/\`plan note\`/\`plan release\`
  send the pushed HEAD (verified by the server); \`fail\` needs none. Without a sprint repository every path stays commit-free and \`done\` skips the push.
Human tickets: the PAT can only comment on them (403 handler_locked for anything else); such a comment waits for human approval, is invisible to
  every agent until then (\`show\` and \`plan revise\` never list it) and carries no commit by default — never use it to pass information to another agent.
Lock: released tickets are read-only for agents — \`plan update\`/\`plan master\` refuse them and \`plan release\` skips them with a warning.
Review gate: \`plan release\` parks every plan in front of a human — \`story find\`, \`next\` and /plan-go refuse a story whose master is
  \`in_review\`; \`plan revise\` is how /plan-steps picks a plan the human sent back.
Resume: \`resume list\` / \`resume <story>\` are for the SAME token picking its own interrupted work back up (/plan-resume, /plan-steps-resume);
  \`next\` never returns in_progress orphans and another token's story is never resumable.
Goals: \`respond next\` locks this token to one comment until \`respond post\` answers it — \`--to\` a reply, \`--summary\` a simplified
  version of an agent's comment — (or a human presses Unlock on the Workers page);
  meanwhile every other write answers 403 goal_locked — tk.ts prints the required \`respond post\` command and exits 11. See \`respond --help\`.
Exit codes: 0 ok · 1 error · 2 usage / no or malformed agent session id · 3 already claimed / story taken · 4 blocked
            · 5 nothing ready / no plan / no eligible story / no planning request / no plan awaiting revision / plan awaiting human review / nothing to resume
            · 6 merge conflict · 7 no sprint repository · 8 push failed · 9 project root not synced / a plan ticket not landed · 10 this token's heartbeat is still fresh (resume --force)
            · 11 goal locked (reply with \`respond post\` first) · 12 the auto worker is halting (take no further ticket).`;

const PUSH_USAGE = `usage: bun .claude/skills/plan-steps/tk.ts push <t> [--remote origin] [--max-rounds 20] [--dry-run]

Merge the ticket's sprint branch into HEAD and push HEAD to it until the push is accepted (plan TICK-111 D8):
  1. the ticket → its sprint → the sprint's repository (URL + integration branch, configured by a human on the Sprints page);
  2. up to --max-rounds times: git fetch <remote> <branch>; when the remote branch exists and is not an ancestor of HEAD,
     git merge --no-edit <remote>/<branch>; git push <remote> HEAD:refs/heads/<branch>; a non-fast-forward rejection
     (another agent pushed in between) starts the next round.
Commit only your ticket's files first (git add <files> && git commit -m "<key>: <summary>"). The working tree may be dirty with
other agents' files — only unresolved conflict markers stop the push. Prints \`pushed <sha> to <remote>/<branch>\`.
--dry-run fetches and prints what would happen without merging or pushing. \`done\` runs this for you; \`comment --push\` too.
Exit codes: 0 pushed · 6 merge conflict (resolve, re-run your verification, push again) · 7 the sprint has no repository
            · 8 fetch/merge/push failed for another reason (stderr shown).`;

const PLAN_LANDED_USAGE = `usage: bun .claude/skills/plan-steps/tk.ts plan landed <master> [--json] [--remote origin]

Say, per done ticket of a plan, whether its work is on the sprint's integration branch (plan TICK-997 D11):
  1. the master → its sprint → the sprint's repository (URL + integration branch, configured by a human on the Sprints page);
  2. one git fetch of that branch from <remote> — the only thing this command changes (a remote-tracking ref);
  3. every \`done\` step, fix, barrier and the master, plus the review items an agent submitted: its commits are the ones its
     verified comments name and the ones reachable from HEAD whose subject starts \`<ticket key>:\` (the enumeration
     \`plan tests\` uses). \`landed\` when every one is an ancestor of <remote>/<branch>, \`not landed\` naming the missing
     commit otherwise, \`no commit\` when the ticket names none (counts as landed).
Prints a \`Ticket · Ref · Commit · State\` table and a last line \`Landed: <n> of <m> done tickets on <remote>/<branch>\`;
--json prints { master, branch, remote, landed, tickets: [{ key, ref, commits, state, missing }] }.
It writes nothing to the server and never touches the working tree, the index or HEAD; run it from the plan's worktree
or from the project root. A ticket that is \`not landed\`: \`tk.ts push <key>\` from the worktree, then run this again.
Exit codes: 0 every done ticket landed (or the plan has none) · 7 the sprint has no repository
            · 9 a ticket is not landed, or the branch could not be fetched (stderr says why).`;

const SYNC_USAGE = `usage: bun .claude/skills/plan-steps/tk.ts sync <t> [--from <rev>] [--remote origin] [--dry-run]

Bring a finished plan into the project root's own checkout, so its work shows up where the user works without a manual pull.
Run it from the PROJECT ROOT (the main checkout) after \`done master\`; a plan worktree is refused.
  1. the source: the ticket's sprint branch, fetched from <remote> — or --from <rev> (the worktree's HEAD, for a sprint
     without a repository);
  2. the target: the root's local copy of the sprint's branch (without a repository: the checked-out branch).
     Checked out → git merge --ff-only; when it has commits of its own, git merge --no-edit — only from a clean tracked
     tree, and aborted on conflict, so the root is never left half-merged. Not checked out → only its ref is
     fast-forwarded (never while another worktree has it out); the root's other branch is left alone, because the
     sprint's branch is never merged into another branch.
Uncommitted work in the root survives: git refuses a fast-forward that would overwrite it, and nothing changes.
--dry-run fetches and prints what would happen.
Exit codes: 0 the checked-out branch contains the plan · 7 no sprint repository and no --from · 9 the checkout was left without
            it (dirty files in the way, a conflict, another branch checked out, fetch failed — stderr says which).`;

const NEXT_USAGE = `usage: bun .claude/skills/plan-steps/tk.ts next [<story name | id | master key> | --story <id>] [--json]

Pull the next ready ticket for this agent through POST /api/work/next (plan TICK-111 D4): the server picks one unblocked agent ticket of a plan,
unassigned or held by the story's owner — limited to the story this PAT owns or already works in, or to the given story — assigns
it to this PAT and starts it (in_progress). /plan-go calls it repeatedly until exit 5 and dispatches one agent per ticket.
Requires an agent session id (--session <id>, TICKETING_SESSION_ID or Claude Code's CLAUDE_CODE_SESSION_ID); it is sent as
agentSessionId and recorded on the ticket.
Prints \`KEY ref kind wave title · plan <master> · session <id>\`; --json prints { key, id, ref, kind, wave, title, status, storyId,
assignee, master, agentSessionId }.
Exit codes: 0 a ticket was assigned · 2 no agent session id, or the PAT may not pull (403: needs work:pull + tickets:claim) · 3 the story is taken by
            another agent · 5 nothing ready for this token.`;

const REVIEW_USAGE = `usage: bun .claude/skills/plan-steps/tk.ts review file   <master> -
       bun .claude/skills/plan-steps/tk.ts review list   <master> [--failed] [--json]
       bun .claude/skills/plan-steps/tk.ts review submit <t> [--plan <master>] [-m <text>] [--tokens-in N --tokens-out M] [--note <text>]
                                                             [--no-push] [--commit <sha> | --no-commit] [--remote origin]

A REVIEW ITEM (plan TICK-391) is a check a person must perform by hand, because the agent that built the thing could not
prove it with a test ("open the board at 1280px and confirm the drag ghost follows the cursor"). /plan-review files one per
human-verifiable claim of a finished plan; /plan-review-fix works the ones that failed.

Its life:
  1. \`review file\` creates it under the plan's master, in the plan's story, agent-handled and in \`backlog\` with the org's
     \`question\` + \`review\` labels (a PAT may label an agent ticket, never a human one), then calls
     POST /api/tickets/:id/review-submit, the one elevated agent → human write, which parks it: handler \`human\`,
     status \`in_review\`, unassigned. An open human ticket HOLDS ITS STORY'S WHOLE QUEUE — \`tk.ts next\` serves nothing
     from that story until every review item in it is settled. That is the design, not a bug.
  2. A human presses "Performing review" (it is claimed and goes \`in_progress\`), then "Review passed" → \`done\`, or
     "Review failed" with a comment saying what went wrong → the item returns to the agents: \`todo\`, handler \`agent\`,
     unassigned, the reason in its comments. Both verdicts are POST /api/tickets/:id/review-decision, which is
     HUMANS ONLY (a PAT gets 403 handler_locked) — tk.ts never calls it and offers no command for it.
  3. \`review list <master> --failed --json\` finds those; claim one by key (the story's owner may, \`next\` will not serve
     it), fix it, and \`review submit\` sends it back to step 2. The same ticket carries the whole history.

\`review file\`: stdin is one document whose first heading is \`# Review NN — title\` (\`**Priority:**\` optional, default high;
  review items are never estimated — no \`**Estimated scope:**\`). Numbering is the plan's: re-filing an existing review-NN
  is refused. The document's \`## \` headings are filed as typed sections (global --flat keeps it one description).
  Prints \`review-NN KEY (id) in_review handler human labels question, review\`.
\`review list\`: columns Ticket · Ref · Status · Handler · Assignee · Verdict · Title, where the verdict is derived —
  \`draft\` (agent, backlog: a \`review file\` that died halfway), \`awaiting\` (human, in_review), \`reviewing\` (human,
  in_progress), \`failed\` (agent and live: sent back), \`passed\` (done), \`cancelled\`. --json prints the same rows as
  objects { key, id, ref, status, handler, assignee, verdict, title }. Exit 5 when the (filtered) list is empty.
\`review submit\`: only for an item this agent holds (handler agent). It pushes first, comments WHILE THE ITEM IS STILL
  AGENT-HANDLED — after the flip to \`human\` a comment would be held for human approval and invisible to every agent —
  records the token usage (a human ticket refuses usage too) and then calls review-submit. This is where a fix's token
  cost is reported: an agent never moves a review item to \`done\`.
Exit codes: 0 ok · 1 not a review item / already with its human / settled · 2 usage · 5 no review item to list
            · 6 merge conflict · 7 no sprint repository · 8 push failed.`;

const REPORT_USAGE = `usage: bun .claude/skills/plan-steps/tk.ts report file [--about <key>] -
       bun .claude/skills/plan-steps/tk.ts report list [--open] [--json]

A REPORT (plan TICK-429) is an agent's finding for a person to read — a bug it noticed next to its ticket, debt, a
follow-up idea — written down instead of acted on. The /report skill files one from a conversation; an executor files one
for anything outside its ticket that a person should know about, and carries on (a report never pauses a plan: only
\`tk.ts ask\` does).

Its life:
  1. \`report file\` creates it agent-handled and in \`backlog\` with the org's \`report\` label (a PAT may label an agent
     ticket, never a human one), with NO story and NO parent, then calls POST /api/tickets/:id/report-submit — the
     third elevated agent → human write — which parks it: handler \`human\`, status \`in_review\`, unassigned. Being
     story-less it HOLDS NO QUEUE: no plan waits for it. It shows on /attention and in the Reports row of the
     organization board.
  2. A human reads it and replies in a comment, then either presses "Promote to plan" — POST /api/tickets/:id/report-promotion,
     HUMANS ONLY (a PAT gets 403 handler_locked; tk.ts never calls it) — which posts "Promoted to plan" plus their note,
     swaps the \`report\` label for \`planning\`, hands the ticket to the agents and walks it to \`todo\`, so
     \`tk.ts plan next\` serves it as a plan request (and prints those comments as the planner's direction); or resolves it
     (Start → Resolve) when no action is needed. A promoted report no longer appears in \`report list\`.

\`report file\`: stdin is one document whose first line is \`# Report — <title>\` (the dash may be —, –, : or -; NO number —
  \`# Report 01 — …\` is refused). \`**Priority:**\` optional, default medium; reports are never estimated, so
  \`**Estimated scope:**\`, \`**Depends on:**\` and \`**Wave:**\` are refused. Suggested sections: Summary, What I found
  (real file paths), Why it matters, Suggested next step — each \`## \` heading is filed as a typed section (global --flat
  keeps the whole document in the description). \`--about TICK-nn\` names the ticket you were working in the
  role line (prose only — the report stays story-less). A missing \`report\` label is a loud warning: the ticket is still
  filed, but report-submit then answers 400 not_a_report. Prints
  \`report KEY (id) in_review handler human labels report — story-less: holds no queue; …\`.
\`report list\`: the project's story-less \`report\`-labelled tickets, newest first — columns Ticket · Status · Handler ·
  Assignee · State · Title, where the state is derived: \`draft\` (agent, backlog: a \`report file\` that died halfway),
  \`awaiting\` (human, not yet started), \`reading\` (human, in_progress), \`resolved\` (done), \`cancelled\`; an
  agent-handled live ticket still labelled \`report\` prints \`agent\`. --open drops resolved and cancelled ones. --json
  prints the same rows as objects { key, id, status, handler, assignee, state, title }. Exit 5 when the list is empty.
No token usage is ever recorded on a report, and tk.ts has no command for the promotion — that is a person's call.
Exit codes: 0 ok · 1 not a report document / no \`report\` label / refused by the server · 2 usage · 5 nothing to list.`;

const SPLIT_USAGE = `usage: bun .claude/skills/plan-steps/tk.ts plan split request [--from <origin key|id>] -
       bun .claude/skills/plan-steps/tk.ts plan split submit  <key>
       bun .claude/skills/plan-steps/tk.ts plan split status  [<origin>] [--json]
       bun .claude/skills/plan-steps/tk.ts plan split release <origin> --tokens-in N --tokens-out M --note estimated [--commit <sha> | --no-commit]

A SPLIT (plan TICK-728) answers a plan request whose deliverable is more plans: instead of a story, a master and steps the
planner files one PLAN REQUEST per plan it cut, each parked for a person's Approve for Planning exactly like a request filed
from the New plan modal. A split files no story, no master and no planning ticket and never calls \`plan open\`: the request
\`plan next\` pulled — the ORIGIN, in_progress for this token — is the unit of work. Notes are comments on it
(\`tk.ts comment <origin> …\`) and the planning usage is recorded on it.

\`plan split request\`: stdin is one generated-request document —

      # <title of the plan to be planned>

      **Plan mode:** plan-full | plan-quick | plan-single | plan-run | plan-run-quick
      **Priority:** <optional, default medium>
      **Depends on requests:** TICK-nn — why (optional)

      <the prompt of that plan: free Markdown; \`## \` headings become sections>

  The title line becomes the ticket's title (no prefix); the \`**Plan mode:**\` and \`**Priority:**\` lines are stripped and the
  rest is filed verbatim as the prompt — preamble → description, each \`## \` heading a typed section (global --flat keeps one
  description), NO \`Role:\` line; \`**Depends on requests:**\` stays in the description as direction for that request's planner.
  \`**Plan mode:**\` is required; \`plan-split\` is refused — a split never generates another split. A refused document exits 2
  and files nothing. The ticket is created agent-handled in \`backlog\` with the org's \`planning\` label and the mode label (a
  missing label is fatal: exit 1, nothing filed), story-less, under the origin when \`--from\` names it — the origin must be a
  plan request this token holds — and then parked with POST /api/tickets/:id/plan-request-submit, the fourth elevated
  agent → human write: handler \`human\`, \`in_review\`, unassigned. Without \`--from\` (a split driven by a prompt) it is filed
  parentless. Prints
  \`request <KEY> (<id>) in_review handler human labels planning, <mode> — from <ORIGIN|prompt>; awaiting Approve for Planning\`.
  When the park fails after the create it warns \`request <KEY> is filed but still a draft (backlog) — …\` and exits 1; a 404
  there means the ticketing server predates plan-request-submit and must be updated.
\`plan split submit\`: re-parks such a draft and prints the same \`request …\` line.
\`plan split status <origin>\`: the plan requests generated under the origin, oldest first — columns Ticket · Mode · Status ·
  Handler · State · Plan · Title. The state is derived: \`draft\` (agent, backlog: a request that was never parked),
  \`awaiting\` (human: waiting for Approve for Planning), \`queued\` (agent, todo, unassigned: \`plan next\` serves it),
  \`planning\` (pulled, no plan under it yet), \`planned\` (a plan master is filed under it — Plan is its key), \`done\`,
  \`cancelled\`. Footer \`<n> plan requests from <ORIGIN> — <a> awaiting a person, <d> drafts\`. Any plan request may be named:
  the planner of a generated request reads its siblings here to resolve \`**Depends on requests:**\`. --json prints the rows
  as objects { key, id, mode, status, handler, state, plan, title }. Exit 5 when the origin generated none.
\`plan split status\` (no argument): this token's unfinished pulls — its in_progress, story-less, \`planning\`-labelled tickets
  with no plan master under them — as Ticket · Mode · Generated · Title (--json: { key, id, mode, generated, title }). An
  interrupted split is continued from here, never restarted: \`plan next\` does not serve the origin again. Exit 5 when none.
\`plan split release\`: refused (exit 1, nothing written) while the origin generated no request or one is still a draft.
  Otherwise it records the usage on the origin (workflow plan-steps) — once: a second run warns
  \`usage already recorded — --tokens-in/--tokens-out ignored\` — comments \`Plan split — <n> plan requests filed\` with the
  table of requests and the "Over to you" paragraph, moves the origin to \`in_review\` and tries to hand it to a human (the
  server lets only a human flip the handler; a warning says so). Each of those failures is a warning. Run again on a released
  origin it only prints the table. A prompt-driven split has no origin and is not released: its usage is not recorded.
Exit codes: 0 ok · 1 not a plan request / not held by this token / missing label / park refused / nothing to release
            · 2 usage or a refused document · 5 nothing to list.`;

const RESPOND_USAGE = `usage: bun .claude/skills/plan-steps/tk.ts respond next [--json] [--request <commentId>]
       bun .claude/skills/plan-steps/tk.ts respond post <key> --to <commentId> (- | --body <text> | --body-file <path>)
       bun .claude/skills/plan-steps/tk.ts respond post <key> --summary <commentId> (- | --body <text> | --body-file <path>)
       bun .claude/skills/plan-steps/tk.ts respond status [--json]

A RESPOND REQUEST (plan TICK-475) is a comment a human marked "Request agent response" (when posting a comment or a reply on
a ticket). An agent answers it in that comment's thread — and does nothing else: responding is a comment, not work. The
/respond skill is the protocol over these three commands.

  \`respond next\`: POST /api/work/respond-request — the server hands this token the OLDEST awaiting comment in its scope
    (no claim, no assignee or status change, no story lock; a request may sit on a done ticket or in another agent's story)
    and GOAL-LOCKS the token to it. Prints \`# KEY — title\`, the status/handler/assignee line, the request id and its thread
    root, "## Comments up to the request" (the ticket's comments visible to this PAT up to and including the request, as
    \`show\` draws threads) and "## Respond to <id>" with the exact \`respond post\` command. Idempotent: while the goal is
    held, pulling again returns the same request. Needs an agent session id. --json prints { key, id, title, status, handler,
    assignee, agentSessionId, kind, ask, request, threadRootId, comments, goal, simplify }.
    THE PIN (plan TICK-1323): \`--request <commentId>\`, else the environment variable TICKETING_RESPOND_REQUEST (set by the
    auto worker for a session started for one request; the flag wins, blank = none), pins the pull to that one awaiting
    comment — the body carries \`commentId\` and \`kinds: ["respond"]\`. When that comment is not waiting any more (answered,
    withdrawn, taken by another token) the server answers 204 and tk.ts prints \`tk: the pinned respond request <id> is not
    waiting any more — nothing pulled\` and exits 5: NEVER pull another request in its place. Against a server that answers
    400 naming \`commentId\` the pull is retried once without the pin, with \`tk: warning: this server cannot pin a respond
    request — pulled the queue's oldest\`.
    THE EFFORT (plan TICK-1798): a respond request prints \`Effort: <Very High|High|Medium|Small>\` directly under \`Kind:\` —
    the effort a person chose for this one response, whose model the auto worker runs it on — or \`Effort: none — the
    worker's configured model\` (also from a server that predates the field); --json carries it as request.agentRequest.effort.
    A simplify request prints no such line.
    AN ASK TICKET (story-less, label \`ask\`) has no body — its thread is the whole question: one line under \`Kind:\` and
    the \`Effort:\` line says so, \`Ask: yes — this ticket has no body; the thread below is the whole question\` (\`ask: true|false\`
    with --json); any other ticket prints no such line.
    The pull asks for both kinds (\`kinds: ["respond", "simplify"]\`; a server that refuses the key is asked once more without
    it) and a \`Kind: respond\` / \`Kind: simplify\` line under the status line says which one came back.
  \`respond post\`: POST /api/tickets/:id/comments { body, respondsTo: <commentId> } — the reply lands in the request's
    thread (the server derives the thread root), marks the request answered and clears the goal, in one transaction. It
    NEVER carries a commit: there is no code to verify. Prints \`responded on KEY — comment <id> answers <commentId> · goal
    cleared\`. The answer is never held for approval, on a human-handled ticket either.
  \`respond status\`: GET /api/pats/me — \`goal: respond · KEY · comment <id> · since <date>\` (for a simplify request
    \`goal: simplify comment <id> on KEY · since <date>\`) plus the post command, or \`no goal — this token is unlocked\`.
    Exit 0 either way.

A SIMPLIFY REQUEST (plan TICK-1254) is the same queue's second kind: a person pressed "Simplify" on a comment an AGENT wrote
and wants a shorter, plainer version of it. The answer is a SUMMARY stored on that comment — never a reply, never a comment.
  \`respond next\` then prints \`Kind: simplify\` and, instead of "## Respond to <id>": "## Comments up to the comment" (context
    only), "## Comment to simplify — <commentId> by <author>" with the comment's body verbatim, "## Latest simpler version"
    when an earlier round produced one, "## Instructions" — the server's own text on how to simplify, printed verbatim and
    to be followed exactly — and "## Simplify <commentId>" with the exact \`respond post <key> --summary <commentId> -\` command.
  \`respond post <key> --summary <commentId>\`: POST /api/comments/:commentId/summaries { body } — only for the token holding
    the simplify goal on that comment; the body is 1…20000 characters (blank or longer is refused before any request, exit
    2, never cut); the server stores the summary and clears the goal in one transaction. Prints \`simplified on KEY — summary
    <id> on comment <commentId> · goal cleared\`. Give exactly one of --to and --summary. 409 simplify_not_taken: the request
    was withdrawn or taken back — \`respond status\` shows the goal.
  Summaries are never served to a token: \`show\`, \`plan next\` and \`respond next\` print the comments without them (only the
    latest one of the comment being simplified is handed over, as the version to beat).

The lock: while a \`respond\` or \`simplify\` goal is held, every other PAT write — next, claim, transitions, done, comments on other tickets,
  PATCH/DELETE of comments — answers 403 forbidden with details.reason \`goal_locked\`; tk.ts prints the server's message,
  the required \`respond post\` command and the unlock sentence, and exits 11. Reads, heartbeats, \`respond next\` and plain
  comments on the goal's ticket still work (under a \`simplify\` goal the summary is the one write: a comment on the ticket
  is refused too, and the command printed is \`respond post <key> --summary <commentId> -\`). Only the answer (\`respondsTo\` in
  that thread, or the summary) or a human's Unlock on the Workers page clears it — tk.ts has no command for the unlock.
Threads: a comment may reply to a top-level comment (parentId), never to a reply (400 comment_depth); a root with live
  replies cannot be discarded (409 has_replies); only a human may request an agent response or pass parentId with it
  (400 human_only); a response goes into the thread of the comment it answers (400 respond_thread_mismatch).
Exit codes: 0 ok · 1 refused (409 respond_not_taken / simplify_not_taken: pull it with \`respond next\` first) · 2 usage / a
            blank or too long summary / both or neither of --to and --summary / no agent session id /
            the PAT may not pull (needs work:pull + comments:write) / the server predates respond requests · 5 nothing awaits
            · 11 goal locked (another command refused while the goal is held)
            · 12 the auto worker is halting (take no further ticket; nothing was taken and no goal is held).`;

const SUMMARY_USAGE = `usage: bun .claude/skills/plan-steps/tk.ts summary show [<project key|id>] [--json]
       bun .claude/skills/plan-steps/tk.ts summary list [--json]
       bun .claude/skills/plan-steps/tk.ts summary propose <origin ticket key|none> [--note <text>] [--dry-run] -

The PUBLIC SUMMARY (plan TICK-1633) is what a project says about itself to the rest of the organization: an ABSTRACT (one
plain-text paragraph, at most ${SUMMARY_ABSTRACT_MAX} characters) and a LEDGER (Markdown, at most ${SUMMARY_LEDGER_MAX} characters — what the project is for, its API
endpoints, CLI commands and skills, one line each; never internals). Both are versioned. An agent READS summaries and never
writes one: a change is a PROPOSAL, which files a human question ticket a person approves or rejects.

\`summary show\`: GET /api/projects/:projectId/summary — the header line (version, when and by whom it was last written),
  \`Visible to agents: yes|no\`, then the abstract and the ledger. The project is the token's own unless a key (\`TICK\`) or
  an id is given; a project of another scope is readable only when a person made its summary available to agents (404
  otherwise). A project nobody has summarised reads as version 0 with empty texts. --json prints the raw summary.

\`summary list\`: GET /api/orgs/:orgId/project-summaries — one row per project this token may read: its own scope
  (Scope \`own\`) and the ones made available to agents (\`other\`), with the abstract cut to 100 characters. --json prints the
  raw list. Read the cards first, then \`summary show <KEY>\` for the one ledger you need.

\`summary propose\`: stdin is one document carrying the WHOLE proposed texts under two headings, in either order:
      ## Abstract
      <one paragraph — it is trimmed and its whitespace runs collapsed to single spaces>
      ## Ledger
      <Markdown; its own \`## \` headings stay inside it>
  Only \`## Abstract\` and \`## Ledger\` (any case) cut the document, and never inside a fenced code block; text above the
  first of them is ignored. A missing, repeated or empty section, or one over its limit, is refused (exit 2), one problem
  per line. The first argument is REQUIRED: the key of the ticket the proposal comes from (a plan's master — the question
  then joins that story) or the word \`none\`. \`--note <text>\` (at most ${SUMMARY_NOTE_MAX} characters) tells the person why.
  --dry-run prints the line diff against the current texts (\`no change\` when there is none), then
  \`dry run — nothing filed\`, and exits 0. Without it an identical proposal is refused (exit 1); otherwise
  POST /api/projects/:projectId/summary/proposals files it and prints
  \`proposal <id> · question <KEY> (<ticket id>) · based on version N\`. A proposal never pauses a plan.
Exit codes: 0 ok · 1 the proposal equals the current summary / not readable · 2 usage or a refused document.`;

const VALUE_OPTS = new Set(["--body", "--body-file", "--title", "--plan", "--tokens-in", "--tokens-out", "--note", "--scope", "--examples", "--bucket", "-m", "--commit", "--remote", "--max-rounds", "--story", "--request", "--from", "--session", "--about", "--to", "--summary", "--class", "--answers"]);
const BOOL_OPTS = new Set(["--hold", "--run", "--json", "--all", "--remove", "--no-commit", "--push", "--no-push", "--dry-run", "--force", "--failed", "--open", "--flat", "--help", "--brief"]);

function parseArgs(argv: string[]): { positional: string[]; opts: Opts } {
  const positional: string[] = [];
  const opts: Opts = new Map();
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i]!;
    if (VALUE_OPTS.has(a)) {
      const v = argv[i + 1];
      if (v === undefined) fail(`${a} needs a value`, EXIT.usage);
      opts.set(a, v);
      i++;
    } else if (a.startsWith("--") && a.includes("=") && VALUE_OPTS.has(a.slice(0, a.indexOf("=")))) {
      opts.set(a.slice(0, a.indexOf("=")), a.slice(a.indexOf("=") + 1));
    } else if (BOOL_OPTS.has(a)) {
      opts.set(a, true);
    } else if (a.startsWith("--")) {
      fail(`unknown option ${a}\n${USAGE}`, EXIT.usage);
    } else {
      positional.push(a);
    }
  }
  return { positional, opts };
}

function usage(): never {
  console.error(USAGE);
  process.exit(EXIT.usage);
}

