export type { PlanRequestDoc, SplitRequestState, Doc, Kind, ReviewVerdict, ReportState, PlanMode, PlanRun, PlanStrategy, Plan, PlanTicket, Comment, PatGoal, CommentAgentRequest, TicketSection, FailureClass, Effort };

if (import.meta.main) {
  const argv = process.argv.slice(2);
  const command = argv[0];
  const { positional, opts } = parseArgs(argv.slice(1));

  if (opts.has("--help") || command === "help" || command === "--help") {
    console.log(command === "push" ? PUSH_USAGE : command === "sync" ? SYNC_USAGE : command === "plan" && positional[0] === "landed" ? PLAN_LANDED_USAGE : command === "next" ? NEXT_USAGE : command === "review" ? REVIEW_USAGE : command === "report" ? REPORT_USAGE : command === "summary" ? SUMMARY_USAGE : command === "respond" ? RESPOND_USAGE : command === "plan" && positional[0] === "split" ? SPLIT_USAGE : USAGE);
    process.exit(EXIT.ok);
  }

  // Plan TICK-333: resolved once (a malformed value exits 2 here); transition() and the claim/pull calls send it.
  currentSession = resolveSession(opts);
  currentSessionId = currentSession?.id ?? null;

  try {
    switch (command) {
      case "me":
        await cmdMe();
        break;
      case "plan": {
        const [sub, ...rest] = positional;
        switch (sub) {
          case "new":
            await cmdPlanNew();
            break;
          case "open":
            await cmdPlanOpen(rest, opts);
            break;
          case "next":
            await cmdPlanNext(opts);
            break;
          case "title":
            await cmdPlanTitle(rest, opts);
            break;
          case "note":
            await cmdPlanNote(rest, opts);
            break;
          case "master":
            await cmdPlanMaster(rest, opts);
            break;
          case "step":
            await cmdPlanStep(rest, opts);
            break;
          case "question":
            await cmdPlanQuestion(rest, opts);
            break;
          case "external":
            await cmdPlanExternal(rest, opts);
            break;
          case "update":
            await cmdPlanUpdate(rest, opts);
            break;
          case "release":
            await cmdPlanRelease(rest, opts);
            break;
          case "revise":
            await cmdPlanRevise(rest, opts);
            break;
          case "latest":
            await cmdPlanLatest(opts);
            break;
          case "list":
            await cmdPlanList(opts);
            break;
          case "calibrate":
            await cmdPlanCalibrate(opts);
            break;
          case "depends":
            await cmdPlanDepends(rest, opts);
            break;
          case "status":
            await cmdPlanStatus(rest);
            break;
          case "tests":
            await cmdPlanTests(rest, opts);
            break;
          case "landed":
            await cmdPlanLanded(rest, opts);
            break;
          case "cancel":
            await cmdPlanCancel(rest);
            break;
          case "split": {
            const [action, ...args] = rest;
            switch (action) {
              case "request":
                await cmdPlanSplitRequest(args, opts);
                break;
              case "submit":
                await cmdPlanSplitSubmit(args);
                break;
              case "status":
                await cmdPlanSplitStatus(args, opts);
                break;
              case "release":
                await cmdPlanSplitRelease(args, opts);
                break;
              default:
                console.error(SPLIT_USAGE);
                process.exit(EXIT.usage);
            }
            break;
          }
          default:
            usage();
        }
        break;
      }
      case "story": {
        const [sub, ...rest] = positional;
        switch (sub) {
          case "list":
            await cmdStoryList(opts);
            break;
          case "find":
            await cmdStoryFind(rest, opts);
            break;
          case "take":
            await cmdStoryTake(rest, opts);
            break;
          case "release":
            await cmdStoryRelease(rest, opts);
            break;
          default:
            usage();
        }
        break;
      }
      case "next":
        await cmdNext(positional, opts);
        break;
      case "respond": {
        const [sub, ...rest] = positional;
        switch (sub) {
          case "next":
            await cmdRespondNext(opts);
            break;
          case "post":
            await cmdRespondPost(rest, opts);
            break;
          case "status":
            await cmdRespondStatus(opts);
            break;
          default:
            console.error(RESPOND_USAGE);
            process.exit(EXIT.usage);
        }
        break;
      }
      case "resume": {
        const [sub, ...rest] = positional;
        if (sub === "list" || sub === undefined) await cmdResumeList(opts);
        else await cmdResume([sub, ...rest], opts);
        break;
      }
      case "push":
        await cmdPush(positional, opts);
        break;
      case "sync":
        await cmdSync(positional, opts);
        break;
      case "ready":
        await cmdReady(positional, opts);
        break;
      case "claim":
        await cmdClaim(positional, opts);
        break;
      case "start":
        await cmdStart(positional, opts);
        break;
      case "show":
        await cmdShow(positional, opts);
        break;
      case "get":
        await cmdGet(positional, opts);
        break;
      case "comment":
        await cmdComment(positional, opts);
        break;
      case "heartbeat":
        await cmdHeartbeat(positional);
        break;
      case "session":
        await cmdSession(positional, opts);
        break;
      case "done":
        await cmdDone(positional, opts);
        break;
      case "fail":
        await cmdFail(positional, opts);
        break;
      case "ask":
        await cmdAsk(positional, opts);
        break;
      case "fix":
        await cmdFix(positional, opts);
        break;
      case "review": {
        const [sub, ...rest] = positional;
        switch (sub) {
          case "file":
            await cmdReviewFile(rest, opts);
            break;
          case "list":
            await cmdReviewList(rest, opts);
            break;
          case "submit":
            await cmdReviewSubmit(rest, opts);
            break;
          default:
            console.error(REVIEW_USAGE);
            process.exit(EXIT.usage);
        }
        break;
      }
      case "report": {
        const [sub, ...rest] = positional;
        switch (sub) {
          case "file":
            await cmdReportFile(rest, opts);
            break;
          case "list":
            await cmdReportList(opts);
            break;
          default:
            console.error(REPORT_USAGE);
            process.exit(EXIT.usage);
        }
        break;
      }
      case "summary": {
        const [sub, ...rest] = positional;
        switch (sub) {
          case "show":
            await cmdSummaryShow(rest, opts);
            break;
          case "list":
            await cmdSummaryList(opts);
            break;
          case "propose":
            await cmdSummaryPropose(rest, opts);
            break;
          default:
            console.error(SUMMARY_USAGE);
            process.exit(EXIT.usage);
        }
        break;
      }
      default:
        usage();
    }
  } catch (e) {
    if (e instanceof ApiError) {
      const hint = hintFor(e);
      // A halting auto worker (plan TICK-867 D6) is one line and exit 12 — no HTTP noise an agent could read as a failure.
      if (hint && hint.exit === EXIT.draining) fail(hint.text, hint.exit);
      fail(`${e.message}${e.details ? ` ${JSON.stringify(e.details)}` : ""}${hint ? `\n    → ${hint.text}` : ""}`, hint?.exit ?? EXIT.error);
    }
    throw e;
  }
} // end if (import.meta.main)
